const touchConversation = `-- name: TouchConversation :execrows
UPDATE conversation SET last_message_at = $1, last_author_member_id = $2
WHERE id = $3 AND status = 'open'
`

type TouchConversationParams struct {
	At             *time.Time
	AuthorMemberID *uuid.UUID
	ID             uuid.UUID
}

// The first half of writing a message: who spoke last, WHERE the
// conversation is open. It takes the conversation's row lock, so a close
// waits for the message or the message finds it closed (no row), and two
// messages in one conversation are written one after the other.
func (q *Queries) TouchConversation(ctx context.Context, arg TouchConversationParams) (int64, error) {
	result, err := q.db.Exec(ctx, touchConversation, arg.At, arg.AuthorMemberID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
